// PreToolUse hook with its own logic: only blocks switching debug on
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const i = JSON.parse(d).tool_input || {};
  const neu = (i.new_string || "") + (i.content || "");
  if (/"debug"\s*:\s*true/.test(neu)) {
    console.error("Blocked by hook: debug must not be switched on.");
    process.exit(2);
  }
  process.exit(0);
});
